// 1. Trích xuất payload an toàn từ RabbitMQ message
const item = $input.first().json;
let payload = {};

if (item.content) {
  try {
    payload = typeof item.content === 'string' ? JSON.parse(item.content) : item.content;
  } catch (err) {
    payload = {};
  }
} else {
  payload = item;
}

// Support both wrapped event ({ data: { ... } }) and flat event
const eventData = payload.data || payload;
const leadId = eventData.leadId || payload.leadId || null;
const workflowRunId = eventData.workflowRunId || payload.workflowRunId || null;
const rawEmail = (eventData.email || payload.email || '').trim().toLowerCase();
const rawWebsite = (eventData.website || eventData.companyWebsite || payload.website || payload.companyWebsite || '').trim();
const provider = eventData.provider || payload.provider || 'mock';
const companyName = eventData.companyName || payload.companyName || '';

// 2. Trích xuất domain từ email (nếu website rỗng)
let emailDomain = '';
if (rawEmail.includes('@')) {
  emailDomain = rawEmail.split('@')[1].trim().toLowerCase();
}

const freeEmailProviders = new Set([
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'live.com', 'icloud.com', 'mail.com', 'aol.com'
]);
const isFreeEmail = freeEmailProviders.has(emailDomain);

// 3. Chuẩn hóa URL website: bỏ https://, http://, www, trailing slash, path
let normalizedDomain = '';
let cleanWebsiteUrl = '';

if (rawWebsite) {
  normalizedDomain = rawWebsite
    .replace(/^(?:https?:\/\/)?(?:www\.)?/i, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .split(':')[0]
    .trim()
    .toLowerCase();
  cleanWebsiteUrl = `https://${normalizedDomain}`;
} else if (!isFreeEmail && emailDomain) {
  normalizedDomain = emailDomain;
  cleanWebsiteUrl = `https://${emailDomain}`;
}

// Fallback domain nếu không có thông tin hợp lệ (ưu tiên slug tên công ty nếu có)
if (!normalizedDomain) {
  if (companyName) {
    const slug = companyName.toLowerCase().replace(/[^a-z0-9]/g, '');
    normalizedDomain = slug ? `${slug}.com` : 'enterprise.com';
  } else {
    normalizedDomain = 'enterprise.com';
  }
}

return [{
  json: {
    leadId,
    workflowRunId,
    provider,
    email: rawEmail,
    emailDomain,
    isFreeEmail,
    domain: normalizedDomain,
    website: cleanWebsiteUrl,
    companyName,
    rawEvent: payload
  }
}];

// Chuẩn hóa và validate kết quả enrichment trả về từ Provider/AI
const response = $input.first().json;
const prep = $('Normalize Email & Domain').first().json;

// 1. Kiểm tra nếu HTTP Request thất bại
if (response.error || (response.statusCode && response.statusCode >= 400)) {
  const errMsg = response.error?.message || response.message || 'External enrichment service call failed after retries';
  return [{
    json: {
      leadId: prep.leadId,
      workflowRunId: prep.workflowRunId,
      status: 'FAILED',
      provider: prep.provider || 'n8n',
      errorMessage: errMsg,
      rawResponse: response
    }
  }];
}

// 2. Xử lý và mapping linh hoạt từ cấu trúc API ngoài (Clearbit / Apollo / Mock)
const company = response.company || {};
const contact = response.contact || {};

const companyName = company.name || response.companyName || prep.companyName || null;
const companyWebsite = company.website || response.companyWebsite || prep.website || (prep.domain ? `https://${prep.domain}` : null);
const industry = company.industry || response.industry || response.companyIndustry || null;

let companySize = null;
if (typeof company.size === 'number') {
  companySize = company.size;
} else if (typeof response.companySize === 'number') {
  companySize = response.companySize;
} else if (typeof company.size === 'string') {
  const match = company.size.match(/\d+/);
  companySize = match ? parseInt(match[0], 10) : null;
}

const jobTitle = contact.jobTitle || response.jobTitle || response.contactJobTitle || null;
const linkedInUrl = contact.linkedinUrl || response.linkedInUrl || response.contactLinkedinUrl || null;

// 3. Đánh giá tính hợp lệ của dữ liệu
const isSuccess = Boolean(companyName || industry || companySize || jobTitle);
const status = isSuccess ? 'SUCCESS' : 'FAILED';
const errorMessage = isSuccess ? null : 'Enrichment provider returned empty data for the given domain/email';

return [{
  json: {
    leadId: prep.leadId,
    workflowRunId: prep.workflowRunId,
    status,
    provider: response.provider || prep.provider || 'n8n',
    companyName,
    companyWebsite,
    industry,
    companySize,
    jobTitle,
    linkedInUrl,
    rawResponse: response.rawResponse || response,
    errorMessage
  }
}];

parameters.jsonBody:
={{ (() => {
  let leadId = null;
  let workflowRunId = null;
  try {
    leadId = $json?.leadId || $json?.execution?.error?.context?.leadId || null;
    workflowRunId = $json?.workflowRunId || $json?.execution?.error?.context?.workflowRunId || null;
  } catch (e) {}
  if (!leadId || !workflowRunId) {
    try {
      const trig = $('RabbitMQ Trigger')?.first()?.json;
      if (trig) {
        let payload = trig.content;
        if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) {} }
        const eventData = payload?.data || payload || {};
        leadId = leadId || eventData.leadId || null;
        workflowRunId = workflowRunId || eventData.workflowRunId || null;
      }
    } catch (e) {}
  }
  if (!leadId || !workflowRunId) {
    try {
      const norm = $('Normalize Email & Domain')?.first()?.json;
      if (norm) {
        leadId = leadId || norm.leadId || null;
        workflowRunId = workflowRunId || norm.workflowRunId || null;
      }
    } catch (e) {}
  }
  const errorMessage = $json?.execution?.error?.message || $json?.message || 'Workflow execution failed with unexpected error';
  return JSON.stringify({
    leadId,
    workflowRunId,
    status: 'FAILED',
    provider: 'n8n',
    errorMessage: String(errorMessage),
    rawResponse: $json || {}
  });
})() }}
